package io.github.diodeme.ji.security.secret;

import java.util.Map;
import java.util.Objects;

/** Maps opaque key ids to external source references without persisting key material. */
public final class SecretSourceKeyResolver implements MasterKeyResolver {
    private final String activeKeyId;
    private final Map<String, KeyReference> references;
    private final Map<SecretSource.Kind, SecretSource> sources;

    public SecretSourceKeyResolver(String activeKeyId, Map<String, KeyReference> references,
            Map<SecretSource.Kind, SecretSource> sources) {
        if (activeKeyId == null || activeKeyId.isBlank()) throw new IllegalArgumentException("activeKeyId must not be blank");
        this.activeKeyId = activeKeyId;
        this.references = Map.copyOf(references);
        this.sources = Map.copyOf(sources);
        if (!this.references.containsKey(activeKeyId)) throw new IllegalArgumentException("active key reference is missing");
    }

    @Override
    public MasterKey activeKey() {
        return keyById(activeKeyId);
    }

    @Override
    public MasterKey keyById(String keyId) {
        KeyReference reference = references.get(keyId);
        if (reference == null) throw new IllegalArgumentException("unknown keyId");
        SecretSource source = sources.get(reference.kind());
        if (source == null) throw new IllegalStateException("secret source adapter is unavailable");
        try (SecretValue value = source.read(reference.reference())) {
            return value.useBytes(bytes -> new MasterKey(keyId, bytes));
        }
    }

    public record KeyReference(SecretSource.Kind kind, String reference) {
        public KeyReference {
            Objects.requireNonNull(kind, "kind");
            if (reference == null || reference.isBlank()) throw new IllegalArgumentException("reference must not be blank");
        }

        @Override
        public String toString() {
            return "KeyReference[kind=" + kind + ", reference=REDACTED]";
        }
    }
}
